// Copies the pinned broker runtime into src/ for the ClojureScript build:
// shadow-cljs cannot require files outside its source roots, and vendor/
// must stay where the PINS test reads it. This file is gitignored and
// regenerated by the pretest hook and by build.mjs.
import { copyFile, mkdir } from "node:fs/promises";

await mkdir(new URL("../src/", import.meta.url), { recursive: true });
await copyFile(
  new URL("../vendor/kotoba-client-runtime.js", import.meta.url),
  new URL("../src/vendor-runtime.gen.js", import.meta.url),
);

// Exact product adapter from packages/awai-inference, vendored for the isolated Nix shell closure.
const {readFile}=await import('node:fs/promises');
const {createHash}=await import('node:crypto');
const inference=new URL('../vendor/awai-inference-client.js',import.meta.url);
const pin=JSON.parse(await readFile(new URL('../vendor/INFERENCE-PINS.json',import.meta.url),'utf8'));
if(createHash('sha256').update(await readFile(inference)).digest('hex')!==pin.sha256)throw Error('inference-client-pin-drift');
await copyFile(inference,new URL('../src/inference-client.gen.js',import.meta.url));

// Gyosei guest (AWAI-3148): an opaque, digest-pinned artifact from network-awai/app-itonami-egov.
// It runs only inside mountRestrictedClientApp; the shell never imports its code.
const {writeFile}=await import('node:fs/promises');
const egovPin=JSON.parse(await readFile(new URL('../vendor/egov/PINS.json',import.meta.url),'utf8'));
const egovBytes=await readFile(new URL('../vendor/egov/'+egovPin.file,import.meta.url));
if(egovBytes.length!==egovPin.bytes||createHash('sha256').update(egovBytes).digest('hex')!==egovPin.sha256)throw Error('egov-guest-pin-drift');
await writeFile(new URL('../src/egov-guest.gen.js',import.meta.url),
  '// Generated by scripts/sync-vendor.mjs from vendor/egov; do not edit.\n'
  +'export const GYOSEI_GUEST_HTML = '+JSON.stringify(egovBytes.toString('utf8'))+';\n'
  +'export const GYOSEI_GUEST_DECLARATION = Object.freeze('+JSON.stringify({revision:egovPin.revision,sha256:egovPin.sha256,'max-bytes':egovPin.bytes})+');\n');
